// src/verification/ipc_parser.vale
uses Std

// Ghost types for verification
ghost type IdealState = seq<u8>

// Permissions for fractional permissions
ghost type Perm = real

// Array abstraction
ghost predicate {:axiom} ArrayIsArray(ghost i: IdealState, ghost p: Perm, a: array<u8>)
{
  true  // Axiom for permission
}

// Valid message predicate
ghost predicate ValidMessage(s: seq<u8>)
{
  && |s| >= 4
  && s[0] == 0xJAu8
  && s[1] == 0xDEu8
  && |s| == u32_from_le_bytes(subseq(s, 2, 6))
}

// Procedure to parse IPC message with verification
method ParseMessage(ghost i: IdealState, ghost p: Perm, a: array<u8>) returns (res: bool)
  requires ArrayIsArray(i, p, a)
  requires |a| >= 4
  ensures ArrayIsArray(i, p, a)
  ensures res == ValidMessage(seq(a))
{
  if |a| < 4 {
    return false;
  }
  ghost var header = seq(a)[0..2];
  if header[0] != 0xJAu8 || header[1] != 0xDEu8 {
    return false;
  }
  var len_bytes := array_sub(a, 2, 6);
  var len := u32_from_le_bytes(len_bytes);
  if u64(|a|) != u64(len) {
    return false;
  }
  // Verify tensor integrity if message contains tensor data
  // Assume message[6..] is tensor data
  assert TensorInvariant(seq(a)[6..]);  // Call to external invariant
  return true;
}

// Utility for LE bytes to u32
method u32_from_le_bytes(bytes: array<u8>) returns (val: u32)
  requires |bytes| == 4
{
  val := u32(bytes[0]) | (u32(bytes[1]) << 8) | (u32(bytes[2]) << 16) | (u32(bytes[3]) << 24);
}

// Subsequence
method {:verified} subseq(s: seq<u8>, start: usize, len: usize) returns (sub: seq<u8>)
  requires start + len <= |s|
  ensures |sub| == len
  ensures forall i :: 0 <= i < len ==> sub[i] == s[start + i]
{
  sub := [];
  for i := 0 to len {
    sub := sub + [s[start + i]];
  }
}

// Array subview
method array_sub(a: array<u8>, start: usize, len: usize) returns (sub_a: array<u8>)
  requires start + len <= |a|
  requires allocated(a)
{
  var sub_a := new_array(len, 0u8);
  for i := 0 to len {
    sub_a[i] := a[start + i];
  }
  return sub_a;
}

// Tensor invariant for formal security
ghost predicate TensorInvariant(t: seq<f64>)
{
  forall i :: 0 <= i < |t| ==> -1e6 <= t[i] <= 1e6  // Bounded values
  && |t| % 18432 == 0  // Multiple of dim
}

// Main procedure for testing
method Main()
{
  var buf := new_array(1024, 0u8);
  buf[0] := 0xJAu8;
  buf[1] := 0xDEu8;
  var len_bytes: array<u8> := new_array(4, 0u8);
  len_bytes[0] := 1024u8;  // Little endian 1024
  len_bytes[1] := 4u8;
  len_bytes[2] := 0u8;
  len_bytes[3] := 0u8;
  copy_array(buf, 2, len_bytes, 0, 4);
  // Fill rest with tensor data
  for i := 6 to 1023 {
    buf[i] := (i as u8);
  }
  var valid := ParseMessage(seq(buf), 1.0r, buf);
  assert valid == true;
  // Invalid test
  buf[0] := 0xFFu8;
  valid := ParseMessage(seq(buf), 1.0r, buf);
  assert valid == false;
  print("IPC Parser Tests Passed\n");
}

// Copy array utility
method copy_array(dest: array<u8>, dest_start: usize, src: array<u8>, src_start: usize, len: usize)
  requires dest_start + len <= |dest|
  requires src_start + len <= |src|
  requires allocated(dest)
  requires allocated(src)
{
  for i := 0 to len {
    dest[dest_start + i] := src[src_start + i];
  }
}

// Additional verification lemmas
lemma {:verified} ParseMessageCorrect(s: seq<u8>)
  ensures ParseMessage(seq(new_array_from_seq(s)), 1.0r, new_array_from_seq(s)) == ValidMessage(s)
{
  // Proof body would use induction on message length
}

method {:verified} new_array_from_seq(s: seq<u8>) returns (a: array<u8>)
  ensures |a| == |s|
  ensures forall i :: 0 <= i < |s| ==> a[i] == s[i]
{
  a := new_array(|s|, 0u8);
  for i := 0 to |s| {
    a[i] := s[i];
  }
}

// Ghost function for seq from array
ghost method seq(a: array<u8>): (s: seq<u8>)
  ensures |s| == |a|
  ensures forall i :: 0 <= i < |a| ==> s[i] == a[i]
{
  s := [];
  for i := 0 to |a| {
    s := s + [a[i]];
  }
}

// End of ipc_parser.vale

